pbccCard_manageCharts = function (locationId) {
	console.log('Managing Charts');

	// Primary chained requests that feed multiple charts
	const urlsPrimary = [
		pbccCard_endpoint('historical_emissions/v2/') + locationId + '.json',
		pbccCard_endpoint('population/') + locationId + '.json',
		pbccCard_endpoint('lsoa_overview/v1/') + locationId + '.json',
		// The GB comparison row lives in the la_emissions dataset under the ID
		// 'GB' (see make_la_summary() in build/R/la_summaries.R), so it follows
		// whatever the host page maps 'la_emissions/v2/' to rather than being
		// pinned to the old JSON folder.
		pbccCard_endpoint('la_emissions/v2/') + 'GB.json'
	];

	const primary = Promise.all(urlsPrimary.map(function (u) { return pbccCard_fetchJSON(u).catch(function () { return null; }); }))
		.then(([historicalData, populationData, overviewArr, GBData]) => {
			if (!historicalData) { return; }
			pbccCard_locationData = historicalData;
			pbccCard_populationLocationData = populationData || {};
			pbccCard_lsoaOverviewData = (overviewArr ? overviewArr[0] : null);
			pbccCard_gbHistoricalData = GBData || {};

			// Which comparisons this report can draw.
			//
			// "Similar areas" is the area classification of a NEIGHBOURHOOD, so it
			// only exists at LSOA level and is left out entirely above it.
			//
			// The local authority comparison needs a parent authority. At LSOA
			// level that comes from the overview record; on the area reports there
			// is no overview record, so the host page supplies it via
			// window.REPORT_CARD_PARENT_LA (see reports/la-report.js). A local
			// authority report sets none, because comparing an authority with
			// itself would just draw the same line twice.
			const parentLA = window.REPORT_CARD_PARENT_LA || null;
			const laCode = (pbccCard_lsoaOverviewData && pbccCard_lsoaOverviewData.LAD25CD) ||
				(parentLA && parentLA.code) || null;
			// At LSOA level the authority is unambiguous and the generic label
			// keeps this card matching the tool's own modal. On the area reports
			// the authority is named, because a constituency can straddle several
			// and a bare "Local Authority" would imply it had only one.
			pbccCard_laLabel = (!pbccCard_lsoaOverviewData && parentLA && parentLA.name)
				? parentLA.name
				: 'Local Authority';

			const urlsSecondary = [
				pbccCard_lsoaOverviewData
					? pbccCard_endpoint('oac_emissions/v2/') + pbccCard_lsoaOverviewData.lsoa_class_code + '.json'
					: null,
				laCode ? pbccCard_endpoint('la_emissions/v2/') + laCode + '.json' : null
			];

			return Promise.all(urlsSecondary.map(function (u) {
					return u ? pbccCard_fetchJSON(u).catch(function () { return null; }) : Promise.resolve(null);
				}))
				.then(([oacData, laData]) => {
					pbccCard_laHistoricalData = laData || {};
					pbccCard_oacHistoricalData = oacData || {};

					pbccCard_makeChartHistorical();
					pbccCard_makeChartPopulation();
					//console.log(lsoaHeadlineData);
					if (pbccCard_lsoaOverviewData) { pbccCard_switchPenPortSub(pbccCard_lsoaOverviewData.lsoa_class_name); }
					if (pbccCard_lsoaOverviewData) { pbccCard_switchPenPortSup(pbccCard_lsoaOverviewData.lsoa_class_name); }
					if (pbccCard_lsoaOverviewData) { pbccCard_lsoaCharacteristicsTable(pbccCard_lsoaOverviewData); }
				});
		})
		.catch(error => {
			console.error('Failed to load primary pbcc datasets:', error);
		});

	// Independent fetches
	/* Will be moved to retrofit tool
	const pVOA2010 = pbccCard_fetchJSON(pbccCard_endpoint('voa_2010/') + locationId + '.json')
		.then(data => { pbccCard_voa2010LocationData = data; pbccCard_makeChartVOA2010(); })
		.catch(err => { console.error('VOA2010 failed:', err); });

	const pVOA2020 = pbccCard_fetchJSON(pbccCard_endpoint('voa_2020/') + locationId + '.json')
		.then(data => { pbccCard_voa2020LocationData = data; pbccCard_makeChartVOA2020(); })
		.catch(err => { console.error('VOA2020 failed:', err); });
	*/
	const pCommunity = pbccCard_fetchJSON(pbccCard_endpoint('community_photo/v1/') + locationId + '.json')
		.then(data => { pbccCard_communityPicLocationData = data; pbccCard_makeCommunityPic(); })
		.catch(err => { console.error('Community photo failed:', err); });

    return Promise.all([primary,  pCommunity]); //pVOA2010, pVOA2020,
};

pbccCard_makeCommunityPic = function(){
  
  const names = pbccCard_communityPicLocationData["id"];
  const numbers = pbccCard_communityPicLocationData["pic"];
  const repeatedNames = numbers.flatMap((num, index) => Array(num).fill(names[index]));
  
  repeatedNames.forEach((name, index) => {
      const img = document.getElementById(`ff${index}`);
      if (img) {
          img.src = `/images/ui/family_photos/${name}.webp`;
          img.setAttribute('title', `${name}`.replaceAll('_', ' '));
      }
  });
}


