  pbccCard_consumptionFlightsChart = makeStandardConsumptionChart('consumptionFlights-chart','Flights');
  pbccCard_consumptionVehiclePurchaseChart = makeStandardConsumptionChart('consumptionVehiclePurchase-chart','Vehicle Purchase');
